<?php
header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');require_once __DIR__.'/auth_common.php';$me=requireAdmin(true);$db=crimsonDb();
function out($x,$c=200){http_response_code($c);echo json_encode($x,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT);exit;}
try{$action=$_GET['action']??'list';$body=json_decode(file_get_contents('php://input'),true)?:[];
 if($action==='list'){$users=array_map(function($u){unset($u['password_hash']);return $u;},$db->rows('__crimson_users'));$mods=[];$root=dirname(__DIR__).'/modulos';foreach(scandir($root) as $id){if($id==='.'||$id==='..')continue;$m=moduleConfig($id);if($m)$mods[]=['modulo'=>$id,'nombre'=>$m['nombre']??ucfirst($id)];}out(['ok'=>true,'users'=>$users,'modules'=>$mods,'permissions'=>$db->rows('__crimson_permissions')]);}
 if($action==='save'){$id=(int)($body['Identificador']??0);$username=trim($body['username']??'');$nombre=trim($body['nombre']??'');if($username===''||$nombre==='')throw new Exception('Nombre y usuario son obligatorios');$d=['username'=>$username,'nombre'=>$nombre,'email'=>trim($body['email']??''),'rol'=>($body['rol']??'usuario')==='admin'?'admin':'usuario','activo'=>!empty($body['activo'])?1:0];if(!empty($body['password']))$d['password_hash']=password_hash($body['password'],PASSWORD_DEFAULT);if($id){$db->update('__crimson_users',$id,$d);}else{if(empty($body['password']))throw new Exception('La contraseña es obligatoria');$d['creado_en']=date('Y-m-d H:i:s');$id=$db->insert('__crimson_users',$d);}out(['ok'=>true,'Identificador'=>$id]);}
 if($action==='delete'){$id=(int)($body['Identificador']??0);if($id===(int)$me['Identificador'])throw new Exception('No puedes eliminar tu propio usuario');$db->deleteWhere('__crimson_permissions','usuario_id',$id);$db->delete('__crimson_users',$id);out(['ok'=>true]);}
 if($action==='permissions'){$uid=(int)($body['usuario_id']??0);$rows=$body['permissions']??[];$db->begin();try{$db->deleteWhere('__crimson_permissions','usuario_id',$uid);foreach($rows as $r){if(!preg_match('/^[a-zA-Z0-9_-]+$/',$r['modulo']??''))continue;$db->insert('__crimson_permissions',['usuario_id'=>$uid,'modulo'=>$r['modulo'],'puede_seleccionar'=>!empty($r['seleccionar'])?1:0,'puede_insertar'=>!empty($r['insertar'])?1:0,'puede_actualizar'=>!empty($r['actualizar'])?1:0,'puede_eliminar'=>!empty($r['eliminar'])?1:0]);}$db->commit();}catch(Throwable $e){$db->rollback();throw $e;}out(['ok'=>true]);}
 throw new Exception('Acción desconocida');
}catch(Throwable $e){if($db->inTransaction())$db->rollback();out(['ok'=>false,'error'=>$e->getMessage()],500);}
